import{_ as s,a0 as i,w as l,s as u,ao as a,I as p,x as t,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"微軟加入開放 3D 基金會，參與開源 3D 開發 | LCTT x X-CMD","titleTemplate":false,"description":"微軟加入開放 3D 基金會，參與開源 3D 開發 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"微軟加入開放 3D 基金會，參與開源 3D 開發 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"微軟加入開放 3D 基金會，參與開源 3D 開發 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development","title":"微軟加入開放 3D 基金會，參與開源 3D 開發","tag":"202205","desc":""},"relativePath":"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development.md","filePath":"[post].md"}'),d={name:"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development.md"};function D(f,o,m,T,x,w){const e=i("Link");return l(),u("div",null,[o[15]||(o[15]=a('<h1 id="微軟加入開放-3d-基金會-參與開源-3d-開發" tabindex="-1">微軟加入開放 3D 基金會，參與開源 3D 開發 <a class="header-anchor" href="#微軟加入開放-3d-基金會-參與開源-3d-開發" aria-label="Permalink to “微軟加入開放 3D 基金會，參與開源 3D 開發”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/microsoft-696x464.jpg" alt="微軟"></p><p>微軟已經以首席成員的身份加入了<ruby>開放 3D 基金會<rt>Open 3D Foundation</rt></ruby>（O3DF），其他首席成員是 Adobe、AWS、華為、英特爾和 Niantic。微軟的參與為該項目帶來了大量的知識和思想引領，這表明了：通過行業合作，創造一個高保真、功能齊全、不受商業條件限制的開源 3D 引擎是多麼的關鍵。</p><p>微軟首席集團項目經理 Paul Oliver 將加入 O3DF 管理委員會，這表明他將致力於實現基金會的目標，即確保符合開放 3D 社區保持需求與輸入的平衡。基金會的戰略方向和對 3D 可視化、仿真計劃的管理，是由理事會與股東的創新互動來指導的。</p><p>“微軟在創意方面的根基很深，我們希望幫助所有的創作者，無論他們是誰、在哪裏、為哪個平台創作”，Oliver 如是説，“由 Linux 基金會創建的開放 3D 基金會，是朝着幫助更多世界各地的創作者邁出的美妙一步，我們很高興能成為其中的一員。”</p><p>微軟不斷致力於使遊戲製作民主化，並向全世界的遊戲創作者提供其工具和技術。加入開放 3D 基金會也反映出這一點。微軟去年通過 GitHub 向所有開發者發佈了其遊戲開發工具包，並正在通過與 O3DF 的新夥伴關係，擴大其向所有人開放技術的承諾。</p><p>O3DF 執行董事，兼 Linux 基金會的遊戲和數字媒體部總經理 Royal O&#39;Brien 説：“我們很高興微軟以首席成員的身份加入開放 3D 基金會。有像微軟這樣傑出的行業資深公司做出貢獻，並幫助社區推動 3D 引擎的創新，這對開源社區和使用它的公司都是巨大的好處。”</p><hr>',8)),p("p",null,[o[1]||(o[1]=t("via: ",-1)),n(e,{href:"https://www.opensourceforu.com/2022/05/microsoft-joins-the-open-3d-foundation-for-open-source-3d-development-promotion/"},{default:r(()=>[...o[0]||(o[0]=[t("https://www.opensourceforu.com/2022/05/microsoft-joins-the-open-3d-foundation-for-open-source-3d-development-promotion/",-1)])]),_:1})]),p("p",null,[o[6]||(o[6]=t("作者：",-1)),n(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...o[2]||(o[2]=[t("Laveesh Kocher",-1)])]),_:1}),o[7]||(o[7]=t(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:r(()=>[...o[3]||(o[3]=[t("lkxed",-1)])]),_:1}),o[8]||(o[8]=t(" 譯者：",-1)),n(e,{href:"https://github.com/lkxed"},{default:r(()=>[...o[4]||(o[4]=[t("lkxed",-1)])]),_:1}),o[9]||(o[9]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[5]||(o[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[o[12]||(o[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[10]||(o[10]=[t("LCTT",-1)])]),_:1}),o[13]||(o[13]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:r(()=>[...o[11]||(o[11]=[t("Linux中國",-1)])]),_:1}),o[14]||(o[14]=t(" 榮譽推出",-1))])])}const F=s(d,[["render",D]]);export{v as __pageData,F as default};
